#include <stdlib.h>
#include <string.h>

static void dfs(int row, int n, int *col, int *d1, int *d2, int *pos,
                char ***ans, int *returnSize, int **returnColumnSizes) {
    if (row == n) {
        char **board = (char **)malloc(n * sizeof(char *));
        for (int r = 0; r < n; ++r) {
            board[r] = (char *)malloc((n + 1) * sizeof(char));
            memset(board[r], '.', n);
            board[r][pos[r]] = 'Q';
            board[r][n] = '\0';
        }
        ans[*returnSize] = board;
        (*returnColumnSizes)[*returnSize] = n;
        ++(*returnSize);
        return;
    }
    for (int c = 0; c < n; ++c) {
        int a = row + c;
        int b = row - c + n - 1;
        if (col[c] || d1[a] || d2[b]) continue;
        col[c] = d1[a] = d2[b] = 1;
        pos[row] = c;
        dfs(row + 1, n, col, d1, d2, pos, ans, returnSize, returnColumnSizes);
        col[c] = d1[a] = d2[b] = 0;
    }
}

char*** solveNQueens(int n, int* returnSize, int** returnColumnSizes) {
    int capacity = 400;
    char ***ans = (char ***)malloc(capacity * sizeof(char **));
    *returnColumnSizes = (int *)malloc(capacity * sizeof(int));
    *returnSize = 0;
    int *col = (int *)calloc(n, sizeof(int));
    int *d1 = (int *)calloc(2 * n - 1, sizeof(int));
    int *d2 = (int *)calloc(2 * n - 1, sizeof(int));
    int *pos = (int *)malloc(n * sizeof(int));
    dfs(0, n, col, d1, d2, pos, ans, returnSize, returnColumnSizes);
    free(col); free(d1); free(d2); free(pos);
    return ans;
}

