class Solution {
public:
    vector<vector<string>> solveNQueens(int n) {
        vector<vector<string>> ans;
        vector<int> pos(n, -1), col(n, 0), d1(2*n-1, 0), d2(2*n-1, 0);
        function<void(int)> dfs = [&](int row) {
            if (row == n) {
                vector<string> board(n, string(n, '.'));
                for (int r = 0; r < n; ++r) board[r][pos[r]] = 'Q';
                ans.push_back(board);
                return;
            }
            for (int c = 0; c < n; ++c) {
                int a = row + c, b = row - c + n - 1;
                if (col[c] || d1[a] || d2[b]) continue;
                col[c] = d1[a] = d2[b] = 1;
                pos[row] = c;
                dfs(row + 1);
                col[c] = d1[a] = d2[b] = 0;
            }
        };
        dfs(0);
        return ans;
    }
};

