class Solution {
    public List<List<String>> solveNQueens(int n) {
        List<List<String>> ans = new ArrayList<>();
        int[] pos = new int[n];
        boolean[] col = new boolean[n];
        boolean[] d1 = new boolean[2*n - 1];
        boolean[] d2 = new boolean[2*n - 1];
        dfs(0, n, pos, col, d1, d2, ans);
        return ans;
    }

    private void dfs(int row, int n, int[] pos, boolean[] col, boolean[] d1, boolean[] d2, List<List<String>> ans) {
        if (row == n) {
            List<String> board = new ArrayList<>();
            for (int r = 0; r < n; ++r) {
                char[] line = new char[n];
                Arrays.fill(line, '.');
                line[pos[r]] = 'Q';
                board.add(new String(line));
            }
            ans.add(board);
            return;
        }
        for (int c = 0; c < n; ++c) {
            int a = row + c, b = row - c + n - 1;
            if (col[c] || d1[a] || d2[b]) continue;
            col[c] = d1[a] = d2[b] = true;
            pos[row] = c;
            dfs(row + 1, n, pos, col, d1, d2, ans);
            col[c] = d1[a] = d2[b] = false;
        }
    }
}

