var solveNQueens = function(n) {
    const result = [];
    const pos = Array(n).fill(-1);
    const cols = Array(n).fill(false);
    const diag1 = Array(2 * n - 1).fill(false);
    const diag2 = Array(2 * n - 1).fill(false);

    function dfs(row) {
        if (row === n) {
            const board = [];
            for (let r = 0; r < n; ++r) {
                const line = Array(n).fill('.');
                line[pos[r]] = 'Q';
                board.push(line.join(''));
            }
            result.push(board);
            return;
        }
        for (let c = 0; c < n; ++c) {
            const a = row + c;
            const b = row - c + n - 1;
            if (cols[c] || diag1[a] || diag2[b]) continue;
            cols[c] = diag1[a] = diag2[b] = true;
            pos[row] = c;
            dfs(row + 1);
            cols[c] = diag1[a] = diag2[b] = false;
        }
    }

    dfs(0);
    return result;
};

